arguments.command:
curl -s -X POST https://slack.com/api/users.list -H 'Authorization: Bearer <TOKEN>' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for u in d.get('members',[]):
    if u.get('deleted'): continue
    real=(u.get('real_name') or '')+' '+(u.get('profile',{}).get('display_name') or '')
    if 'maya' in real.lower() or 'chen' in real.lower():
        print(u['id'], u.get('real_name'), u.get('profile',{}).get('display_name'), u.get('profile',{}).get('title',''))
"

