arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H 'Authorization: Bearer <TOKEN>' -d 'channel=C_LAUNCH&limit=1000' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for m in d.get('messages',[]):
    if m.get('user')=='U_MAYA':
        ts=m.get('ts')
        blocks=m.get('blocks')
        if blocks:
            print('=== TS', ts, '===')
            for b in blocks:
                print(json.dumps(b))
        else:
            print('=== TS', ts, 'text ===')
            print(m.get('text',''))
        print()
"

